import json, re, os

A = "https://mrfix.az/site/assets/files/"
TR = str.maketrans({"ə":"e","Ə":"e","ı":"i","İ":"i","ö":"o","Ö":"o","ü":"u","Ü":"u","ş":"s","Ş":"s","ç":"c","Ç":"c","ğ":"g","Ğ":"g"})
def slug(s):
    s = s.replace("®", " ").translate(TR).lower()
    return re.sub(r"[^a-z0-9]+", "-", s).strip("-")

