out = []
for cat, sub, name, short, img in BRIEF:
    d = DETAIL.get(name, {})
    p = dict(slug=slug(name), name=name, cat=cat, group=sub, short=short, image=A+img, featured=bool(d))
    if d:
        d = dict(d)
        d["tds"] = A + d["tds"] if d.get("tds") else ""
        d["sds"] = A + d["sds"] if d.get("sds") else ""
        d["note"] = T23
        p.update(d)
    out.append(p)

base = os.path.join(os.path.dirname(__file__), "..", "content")
os.makedirs(base, exist_ok=True)
json.dump(out, open(os.path.join(base, "products.json"), "w"), ensure_ascii=False, indent=1)
